            completeFunc: ffi_engine_adapter_sdk_rust_future_complete_rust_buffer,
            freeFunc: ffi_engine_adapter_sdk_rust_future_free_rust_buffer,
            liftFunc: FfiConverterString.lift,
            errorHandler: FfiConverterTypeSdkError.lift
        )
}

private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private var initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 26
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_engine_adapter_sdk_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_func_create_engine() != 23132) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_func_ping() != 18660) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_func_run_pre_authorized_flow() != 61542) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_wmpengine_is_ready() != 45057) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_wmpengine_send() != 19937) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_wmpengine_take_notifications() != 56681) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_request_sign() != 1394) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_request_match() != 22239) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_request_vp() != 43578) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_request_dpop_proof() != 57206) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_request_consent() != 20155) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_request_tx_code() != 41113) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_host_open_authorization() != 25041) {
        return InitializationResult.apiChecksumMismatch
