    if (uniffi_engine_adapter_sdk_checksum_method_host_progress() != 22765) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_engine_adapter_sdk_checksum_method_httpclient_send() != 49403) {
        return InitializationResult.apiChecksumMismatch
